export class MultiPathReasoningValidator {
  constructor() {
    this.paths = [];
  }

  addReasoningPath(path) {
    this.paths.push(path);
  }

  validate() {
    const results = this.paths.map(path => path.execute());
    const consistent = results.every((result, _, arr) => result === arr[0]);
    return { consistent, results };
  }
}

// Example usage
class ReasoningPath {
  constructor(id, logic) {
    this.id = id;
    this.logic = logic;
  }

  execute() {
    return this.logic();
  }
}

const path1 = new ReasoningPath('path1', () => 'output1');
const path2 = new ReasoningPath('path2', () => 'output1');
const validator = new MultiPathReasoningValidator();
validator.addReasoningPath(path1);
validator.addReasoningPath(path2);
const validationResult = validator.validate();
console.log(validationResult);